"""Version-scoped mod choices and related cheat/development questions."""
import re
from azeroth_survivors_content import SOURCES, a, ext, para, ref, steps, table


def register_sources():
    for key, repo, label, scope in [
        ('cm_overhaul', 'finalpantasy/azeroth-survivors-overhaul', 'finalpantasy · Overhaul', 'README describes Windows 10/11, Python 3, a game v0.103.x test target and user-supplied WoW assets for HD packages. Screenshots are author automated preview builds.'),
        ('cm_together', 'bymarvin/azeroth-survivors-together', 'bymarvin · Together', 'README documents a separate co-op installer/updater, Start-Coop.cmd and a linked source repository. Signed-update and rollback statements are author claims.'),
        ('cm_rebuild', 'OutThisLife/azeroth-survivors-re', 'OutThisLife · community rebuild', 'README identifies a community local from-source build on Rust/Bevy and directs players to Aethus for the original. This repository does not establish the original author’s development methods.'),
    ]:
        SOURCES[key] = ('https://github.com/'+repo, 'GitHub · '+label, 'Author documentation read 5 November 2026. '+scope+' No executable, addon installation, multiplayer session or save migration tested here.')


def apply_mods(pages):
    register_sources()
    for page in pages:
        if page['slug'] == 'addons/':
            page['parts'].insert(0, ('mods', 'Looking for mods beyond a HUD or meter?', para('Choose the '+a('mods/', 'mod and client comparison')+' for HD Overhaul, Together and community rebuilds. Those projects have different installation and save boundaries. This page covers addons installed through the original client’s AddOns system.')))
        if page['slug'] == 'save-backup/':
            page['parts'] = [(key, title, body.replace('Our embedded Play page uses a third-party provider, whereas these export instructions describe Aethus’s original.', 'Our Play guide now opens Aethus’s original in a new tab. The former embedded window used a separate third-party provider. These export instructions describe the original.').replace('Read the embedded edition scope', 'Read the former-host save precautions')) for key, title, body in page['parts']]
            page['parts'].append(('cheats', 'Cheats, cheat codes and addon commands', para('Checked 5 November 2026: this guide has no verified working cheat-code list or Cheat Engine table for the current original game. The dated menu and save documentation cited here do not establish a player code-entry workflow. That evidence cannot prove that every private tool or later build lacks one.')+table(['Search or file', 'What it changes', 'Evidence to check'], [['Cheat Engine table / trainer', 'A running process or its memory', 'Exact client, build and process. A native Windows table does not establish browser WebAssembly compatibility.'], ['Save editor / unlocked save', 'Exported progress imported into a destination', 'Tool version, source host and a retained original backup. Import replaces progress.'], ['Addon command', 'A particular addon interface', 'The addon author’s command documentation. A HUD command does not demonstrate an unlock code.']])+para('For documented community editors, use the section above. For gameplay or graphics changes, '+a('mods/', 'compare the mod and client routes')+'. A tool described as a mod, editor or trainer needs its own compatibility evidence. '+ref('saves'))))
    pages.append(dict(id='CM02', slug='mods/', title='Azeroth Survivors Mods: Addons, Overhaul & Together', h1='Choose an Azeroth Survivors mod for your client', desc='Compare Azeroth Survivors addons, HD Overhaul, Together and community rebuilds by platform, game version, installation route and save precautions.', review_note='Reviewed 5 November 2026 · Author documentation and dated original menu · Packages and save transfers not tested', answer='For a meter or HUD, use an addon in the original client. For HD assets, inspect the Windows-only Overhaul requirements. Together and the community rebuild use separate client workflows. Choose the project and its supported version before downloading or moving progress.', parts=[
        ('choose', 'Which kind of mod do you need?', table(['Goal', 'Route', 'First compatibility check'], [['HUD, spell meter or build priorities', a('addons/', 'Original-client addons'), 'Author ZIP/folder instructions and declared game version.'], ['Higher-resolution models or textures', '<a href="#overhaul">HD Overhaul</a>', 'Windows game folder and the exact WoW asset build named by the recipe.'], ['Community co-op setup', '<a href="#together">Together</a>', 'Its separate installer, launch command and release notes.'], ['Build and change a local client', '<a href="#rebuild">Community reconstruction</a>', 'Repository toolchain and user-supplied data requirements.'], ['Change progress or look for cheats', a('save-backup/#cheats', 'Save editing and cheats'), 'Exact tool/client compatibility and an unchanged backup.']])+para('The original menu screenshot below shows the AddOns installation route. It does not show HD Overhaul or Together running. '+ref('game'))),
        ('addons', 'Original-client addons: keep the browser and desktop paths separate', para('The browser accepts addon ZIPs through Options → AddOns → Install AddOns. Desktop users locate the folder through Open AddOns Folder and follow the author’s nesting requirements. An addon changes only what its own code and the client API support. '+ref('addons'))+para(a('addons/', 'Follow browser ZIP or desktop folder setup')+' · '+a('asbuilder/', 'Plan a loadout with ASBuilder')+' · '+a('damage-meter/', 'Compare damage-meter views'))),
        ('overhaul', 'HD Overhaul: Windows files and your own asset source', para('finalpantasy’s README describes optional conversions for models, equipment, world assets and spell effects, alongside new content and a transactional installer. Its requirements name Windows 10/11, Python 3 and a Windows Azeroth Survivors folder. The documented game test target is v0.103.x. That target is older than later original-client references on this site. '+ref('cm_overhaul'))+para('HD packages require your own World of Warcraft install and the build named by the recipe. The repository says it distributes code and recipes, with no game executable or Blizzard assets. Its installer documents planning, verified backups, receipts and rollback. These are author-described features; this guide has not run the converters or verified restoration. '+ref('cm_overhaul'))+steps(['Identify the Windows game version and make a separate backup of the game folder and exported progress.', 'Read the chosen package’s recipe and identify the required asset build and reader dependency.', 'Inspect the installer plan and backup requirements in the author documentation before applying a package.', 'Retain the receipt and original files. Check the author’s rollback procedure before replacing further packages.'])+para(ext('https://github.com/finalpantasy/azeroth-survivors-overhaul', 'GitHub · Overhaul requirements and tools'))),
        ('together', 'Together: choose its separate launcher deliberately', para('bymarvin’s Together repository documents a co-op installer/updater and launches through Start-Coop.cmd. It links a source repository for the DLL, network helper and updater. Its README describes signed releases, file checks, backups and rollback. This guide has not audited those mechanisms or joined a co-op session. '+ref('cm_together'))+para('The original client’s Co-op menu and Together’s launcher are different setup paths. Follow the documentation for the client you actually selected. A separate folder or successful launch does not prove that saves, addons or multiplayer sessions transfer between them. '+a('co-op/', 'Read the original-client co-op scope')+ref('cm_together'))+para(ext('https://github.com/bymarvin/azeroth-survivors-together', 'GitHub · Together setup and releases'))),
        ('rebuild', 'Community rebuilds: a repository is a separate version', para('OutThisLife’s repository describes a local from-source build using a Rust/Bevy client engine and points back to Aethus’s original game. Read its toolchain, data preparation and build instructions as a separate project. A guide for that code snapshot does not establish current original-client mechanics or addon compatibility. '+ref('cm_rebuild'))+para(ext('https://github.com/OutThisLife/azeroth-survivors-re', 'GitHub · community rebuild requirements'))),
        ('before-installing', 'Before changing a client or package', steps(['Record the project author, release/tag, game version, platform and original game address.', 'Export progress from the client and browser where it exists. Export the destination too before any import.', 'Keep addon settings and a clean game folder separately where the project requires them.', 'Change one package first, using the author’s installation method. Check menus and character progress before retaining the change.', 'If a package fails, preserve the original and the release details. Follow its documented removal or rollback path.'])+para('Browser addon storage belongs to its browser and origin. A save import is not an addon transfer. The game validates imported save text and replacement can discard destination progress. '+ref('addons')+ref('saves'))),
        ('questions', 'Can I install these mods in the browser?', para('The original browser addon installer accepts supported addon ZIPs. The Overhaul workflow described above targets Windows game files. Together supplies a separate native launcher. Their requirements cannot be substituted for each other. '+ref('addons')+ref('cm_overhaul')+ref('cm_together'))+para('Does a mod unlock everything? Each project needs its own documented feature and version evidence. For tools that edit progress, '+a('save-backup/#save-editor', 'read the editor and import boundaries')+'. No current-client cheat table or all-unlocked save has been validated here.'))
    ], related=[('addons/', 'Install an original-client addon'), ('save-backup/', 'Keep progress before changing clients'), ('download-platforms/', 'Identify your game source')]))
    return pages


def home_mods(html):
    intro = '<section class="section" id="creator-credit">'
    # Sources already resolved by home(); append the cited short answer before its sources.
    answer = '<section class="section" id="made-with-ai"><h2>Is Azeroth Survivors made with AI?</h2>'+para('As of 5 November 2026, we have not found a verifiable statement from Aethus identifying which AI tools, if any, were used to develop the original game. Community descriptions such as “vibe coded” remain claims. A separate author’s reconstruction or another WoW project cannot establish the original creator’s workflow. The visible game credit identifies Aethus; it does not document development tools. <a href="#creator-credit">See the captured creator credit</a>.')+para('The '+ext('https://github.com/OutThisLife/azeroth-survivors-re', 'GitHub · community rebuild README')+' identifies a separate local build and points to the original. This is an entity check, not evidence for an AI-generated percentage or a statement that the original used no AI.')+'</section>'
    existing = re.search(r'<li id="source-(\d+)"><a href="https://github.com/OutThisLife/azeroth-survivors-re"', html)
    number = existing[1] if existing else str(max(int(n) for n in re.findall(r'id="source-(\d+)"', html))+1)
    source_link = ext('https://github.com/OutThisLife/azeroth-survivors-re', 'GitHub · community rebuild README')
    answer = answer.replace('The '+source_link, 'The community rebuild README <sup class="ref"><a href="#source-'+number+'">['+number+']</a></sup>')
    item = '<li id="source-'+number+'">'+source_link+' — Read 5 November 2026. Identifies a separate local build and credits Aethus for the original. It does not document Aethus’s AI tooling.</li>'
    if not existing:
        html = html.replace('</ol><a class="back" href="#guide">', item+'</ol><a class="back" href="#guide">', 1)
    html = html.replace(intro, answer+intro, 1)
    marker = '<section class="section" id="guides">'
    return html.replace(marker, marker+para(a('mods/', 'Mods: addons, HD Overhaul and community clients')), 1)
